package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.PathVariable;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;

public class ValidateDefer {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody DeferRequest request, Out<ValidDefer> body, Settings settings)
            throws InvalidClaimException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        String until = request.until() == null ? "" : request.until().trim();
        try {
            body.set(new ValidDefer(request.user(), LocalDate.parse(until)));
        } catch (DateTimeParseException e) {
            throw new InvalidClaimException("A deferral needs a date to defer the claim until");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/** Defers an OPEN claim to a date after the sheet's today; not a claim whose due-by is inside a closed period. */
public class ApplyDefer {
    public void apply(@Val ValidDefer request, @Val Claim claim, Sheets sheets, Periods periods)
            throws ClaimStatusRefusedException {
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new ClaimStatusRefusedException("Only an OPEN claim can be deferred");
        }
        if (!request.until().isAfter(sheets.today(claim.getSheetId()))) {
            throw new ClaimStatusRefusedException("A claim can only be deferred to a date after the sheet's today");
        }
        if (periods.isClosed(claim.getSheetId(), claim.getPeriodDate())) {
            throw new ClaimStatusRefusedException("No claim whose due-by is inside a closed period can be deferred");
        }
        claim.setDeferredUntil(request.until());
    }
}
