                + " AND (set_on IS NULL OR set_on <= ?) ORDER BY seq", (RowCallbackHandler) rs -> retired.add(
                        local(rs.getDate(1))), sheetId, now.getId(), end);
        person.setRetiredFrom(retired.isEmpty() ? null : retired.get(retired.size() - 1));
        return person;
